const getPostcardCrumbs = () => {
    const catalogue = new Set(postcards_1.POSTCARD_CATALOGUE);
    const toUse = postcards_1.POSTCARDS.filter(p => catalogue.has(p.id));
    return [
        new Array(8).fill(0).flatMap((_, index) => {
            const category = index + 1;
            const postcards = toUse.filter(p => p.category === category);
            const varName = `category_0${category}`;
            return [
                ...(0, avm1_1.createEmptyObjectVar)(varName),
                ...postcards.flatMap((postcard) => (0, avm1_1.setMember)((0, avm1_1.addVarToStack)(varName), postcard.id, (0, avm1_1.addObjectToStack)({
                    subject: postcard.subject,
                    in_catalog: true
                })))
            ];
        }),
        (0, avm1_1.createEmptyObjectVar)('pc_crumbs'),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'EPF', (0, avm1_1.addVarToStack)('category_01')),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'Featured Postcards', (0, avm1_1.addVarToStack)('category_02')),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'Friendship', (0, avm1_1.addVarToStack)('category_03')),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'Puffles', (0, avm1_1.addVarToStack)('category_04')),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'Party', (0, avm1_1.addVarToStack)('category_05')),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'Games', (0, avm1_1.addVarToStack)('category_06')),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'Rooms', (0, avm1_1.addVarToStack)('category_07')),
        (0, avm1_1.setMember)((0, avm1_1.addVarToStack)('pc_crumbs'), 'From us', (0, avm1_1.addVarToStack)('category_08'))
    ].flat();
};
